static void storage_add(const char *str) { /* <=== storage_add */ 
#ifdef DEBUG
	printf("add %s\n", str);
#endif
	if (!str) {
#ifdef DEBUG
		printf("null pointer passed to storage_add\n");
#endif			
		return;
	}

	ListElem *ptr = malloc(sizeof(ListElem));
	if (!ptr) {
		fprintf(stderr, "Error: cannot allocate memory\n");
		return;
	}
	ptr->path = strdup(str);
	if (!ptr->path) {
		fprintf(stderr, "Error: cannot allocate memory\n");
		free(ptr);
		return;
	}

	// insert it into the hash table
	uint32_t h = hash(ptr->path);
	ptr->next = storage[h];
	storage[h] = ptr;
}

